#!/usr/bin/env python3
"""Launch RLWalk with the policy selected by the PuddleDuck web console.

The web console stores the selected policy name in ``$HOME/policy/.active_policy``.
Keeping the selection in a small text file lets controller actions use one stable
command while policies are uploaded, removed, or switched from the browser.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

_POLICY_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,191}$")
_ALLOWED_SUFFIXES = {".onnx", ".yaml", ".yml"}


def _policy_dir() -> Path:
    return Path(os.environ.get("PUDDLEDUCK_POLICY_DIR", "~/policy")).expanduser().resolve()


def _active_policy_path(policy_dir: Path) -> Path:
    active_file = Path(
        os.environ.get("PUDDLEDUCK_ACTIVE_POLICY_FILE", str(policy_dir / ".active_policy"))
    ).expanduser()
    try:
        name = active_file.read_text(encoding="utf-8").splitlines()[0].strip()
    except (FileNotFoundError, IndexError):
        raise RuntimeError(
            f"No active policy is selected. Choose one in the Policy tab or write a filename to {active_file}."
        )

    if not _POLICY_NAME_RE.fullmatch(name) or Path(name).suffix.lower() not in _ALLOWED_SUFFIXES:
        raise RuntimeError(f"Invalid active policy name in {active_file}: {name!r}")

    path = (policy_dir / name).resolve()
    if path.parent != policy_dir or not path.is_file():
        raise RuntimeError(f"Active policy does not exist: {path}")
    return path


def main(argv: list[str] | None = None) -> int:
    extra_args = list(sys.argv[1:] if argv is None else argv)
    policy_dir = _policy_dir()
    try:
        policy_path = _active_policy_path(policy_dir)
    except RuntimeError as exc:
        print(f"walk: {exc}", file=sys.stderr, flush=True)
        return 2

    # Preserve the behavior of the original test.sh launcher. RLWalk writes
    # the complete policy observation capture and other relative-path output
    # from its working directory, so make that directory the duck user's home rather
    # than whichever directory started broadcast_state.
    os.chdir(Path.home())

    action_scale = os.environ.get("PUDDLEDUCK_ACTION_SCALE", "1.0")
    command = [
        sys.executable,
        "-m",
        "pd.runtime.RLWalk",
        "--sounds",
        "--onnx_model_path",
        str(policy_path),
        "--action_scale",
        str(action_scale),
        "--allow_action",
        *extra_args,
    ]
    print(f"Starting RLWalk with {policy_path.name}", flush=True)
    os.execv(sys.executable, command)
    return 127


if __name__ == "__main__":
    raise SystemExit(main())
